import{_ as e,o as t,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2020-03-12 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2020-03-12 :: Ceph Performance Meeting","date":"2020-03-12T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph 性能","分布式存储","IO 500 测试","性能优化","存储系统"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-03-12_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2020/2020-03-12_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-03-12_-_-_Ceph_Performance_Meeting.md"};function i(n,r,s,g,d,h){return t(),a("div",null,[...r[0]||(r[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li><strong>时间：</strong> 早晨6:30</li><li><strong>参与人员：</strong> Mark, Greg, Igor, Adam, 及其他团队成员</li></ul><h4 id="会议议题与讨论内容" tabindex="-1">会议议题与讨论内容 <a class="header-anchor" href="#会议议题与讨论内容" aria-label="Permalink to &quot;会议议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>项目进展更新</strong></p><ul><li><strong>PR更新：</strong> 本周没有新的或即将关闭的PR。团队成员主要集中在现有问题的处理上。</li><li><strong>更新PR：</strong> Igor更新了关于hybrid alligator的PR，讨论了其改进和合并计划。</li></ul></li><li><p><strong>IO 500测试套件后端开发</strong></p><ul><li><strong>进展：</strong> 后端已成功开发，性能超过内核客户端。</li><li><strong>性能分析：</strong> 发现内核部分可能存在问题，需要修复。</li><li><strong>测试结果：</strong> 在IO 500测试中，团队排名第9，接近第8。</li><li><strong>硬件分类问题：</strong> 讨论了IO 500测试中硬件分类不明确的问题，以及如何在不同系统配置下有效竞争。</li></ul></li><li><p><strong>性能优化讨论</strong></p><ul><li><strong>Adam的测试发现：</strong> 所有alligators在磁盘使用率达到80%后，性能迅速下降。讨论了是否应关注超过80%的磁盘使用情况。</li><li><strong>Igor的优化工作：</strong> 介绍了针对4k min alaq size的优化，包括hybrid alligator和deferred writes的改进。展示了性能数据，并讨论了未来的优化方向。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>Hybrid Alligator的合并：</strong> 计划将hybrid alligator合并到主分支，但不作为默认设置。</li><li><strong>Deferred Writes的调整：</strong> 对于deferred writes的调整，团队决定等待进一步测试和评估。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>继续优化：</strong> 团队将继续优化IO 500测试套件的后端，并关注特定测试案例的性能问题。</li><li><strong>性能测试：</strong> Adam将继续进行性能测试，并在下次会议中分享详细数据。</li><li><strong>代码审查与合并：</strong> Igor将继续进行代码审查，并计划将改进合并到主分支。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>文档共享问题：</strong> 讨论了Google Doc的访问权限问题，Adam将尝试解决文档共享的访问问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li><strong>时间：</strong> 会议在预定时间结束后结束。</li><li><strong>下次会议：</strong> 团队成员将在下次会议中继续讨论和评估性能优化进展。</li></ul><p>本次会议重点关注了Ceph存储系统的性能优化和IO 500测试套件的开发进展。团队成员分享了各自的发现和优化策略，并制定了后续的行动计划。会议讨论了hybrid alligator的合并、deferred writes的调整以及IO 500测试的性能问题。</p>',14)])])}const c=e(o,[["render",i]]);export{u as __pageData,c as default};
